
(() => {
  'use strict';
  const lessons = [{"chapter": 8, "period": "Década de 30 d.C., aproximadamente", "summary": "A perseguição em Jerusalém dispersa discípulos. Filipe anuncia Cristo em Samaria. Pedro e João vão até lá. Na estrada de Jerusalém para Gaza, Filipe explica ao oficial etíope a passagem de Isaías que ele estava lendo e o batiza. Depois, Filipe aparece em Azoto e anuncia o evangelho até chegar a Cesareia.", "people": [["Filipe", "Anuncia Cristo em Samaria e explica as Escrituras ao oficial etíope (8:5–8,26–40)."], ["Oficial etíope", "Lê Isaías, ouve Filipe e pede o batismo (8:27–39)."], ["Pedro e João", "Visitam Samaria e oram pelos que receberam a palavra (8:14–25)."], ["Simão", "Tenta obter com dinheiro a capacidade que viu nos apóstolos (8:9–24)."]], "refs": ["Atos 1:8", "Isaías 53:7–8", "Atos 6:1–6"], "family": "Leiam Atos 8:26–39. Cada pessoa escreve ou diz uma pergunta sobre o texto. Escolham uma e procurem juntos a resposta na leitura.", "points": {"jerusalem": "De Jerusalém saem discípulos dispersos e, depois, Pedro e João (8:1–4,14).", "samaria": "Filipe anuncia Cristo numa cidade de Samaria. O mapa assinala a região (8:5–8).", "gaza": "O encontro ocorre na estrada em direção a Gaza. O ponto marca a cidade, enquanto o local exato do encontro é desconhecido (8:26–39).", "azoto": "Filipe aparece em Azoto e segue anunciando pelas cidades (8:40).", "cesareia": "Cesareia é o destino citado ao fim do percurso de Filipe (8:40)."}, "routes": [["jerusalem", "samaria"], ["jerusalem", "gaza"], ["azoto", "cesareia"]]}, {"chapter": 9, "period": "Década de 30 d.C., aproximadamente", "summary": "Saulo encontra Jesus perto de Damasco. Ananias o visita, e Saulo passa a anunciar Jesus. Depois de escapar de Damasco, ele chega a Jerusalém, onde Barnabé o acolhe. Pedro encontra Eneias em Lida e vai a Jope, onde Tabita volta à vida.", "people": [["Saulo", "De perseguidor, torna-se anunciador de Jesus (9:1–30)."], ["Ananias", "Vai ao encontro de Saulo em Damasco (9:10–19)."], ["Barnabé", "Apresenta Saulo aos apóstolos em Jerusalém (9:26–28)."], ["Eneias e Tabita", "Eneias é curado em Lida. Tabita volta à vida em Jope (9:32–43)."]], "refs": ["Atos 22:6–16", "Atos 26:12–18", "Gálatas 1:15–24"], "family": "Leiam Atos 9:36–42. Identifiquem como Tabita ajudava as pessoas e combinem uma ação concreta de cuidado para esta semana.", "points": {"damasco": "Saulo encontra Jesus nas proximidades. Na cidade, Ananias o visita (9:3–19).", "jerusalem": "Barnabé leva Saulo aos apóstolos (9:26–28).", "cesareia": "Os irmãos levam Saulo a Cesareia e o enviam a Tarso, fora do recorte do mapa (9:30).", "lida": "Pedro encontra Eneias (9:32–35).", "jope": "Pedro é chamado a Jope, onde Tabita volta à vida (9:36–43)."}, "routes": [["jerusalem", "damasco"], ["jerusalem", "cesareia"], ["lida", "jope"]]}, {"chapter": 10, "period": "Fim da década de 30 ou início da década de 40 d.C., aproximadamente", "summary": "Cornélio envia mensageiros a Jope após uma visão. Pedro também recebe uma visão e vai a Cesareia. Na casa de Cornélio, anuncia Jesus. O Espírito Santo vem sobre os ouvintes, e Pedro manda batizá-los.", "people": [["Cornélio", "Centurião em Cesareia que reúne parentes e amigos para ouvir Pedro (10:1–8,24,30–33)."], ["Pedro", "Vai à casa de Cornélio e anuncia Jesus (10:9–48)."]], "refs": ["Atos 11:1–18", "Atos 15:7–11", "Deuteronômio 10:17–19"], "family": "Leiam Atos 10:34–35. Cada pessoa sugere uma atitude de acolhimento para praticar em casa, na escola ou na igreja.", "points": {"cesareia": "Cornélio recebe uma visão e mais tarde acolhe Pedro em sua casa (10:1–8,24–48).", "jope": "Pedro tem uma visão e recebe os mensageiros de Cornélio (10:9–23)."}, "routes": [["cesareia", "jope"]]}, {"chapter": 11, "period": "Início a meados da década de 40 d.C., aproximadamente", "summary": "Em Jerusalém, Pedro explica o que aconteceu na casa de Cornélio. Em Antioquia, Barnabé busca a ajuda de Saulo, e os dois ensinam durante um ano. Ágabo anuncia uma fome, e os discípulos organizam auxílio aos irmãos da Judeia.", "people": [["Pedro", "Relata em Jerusalém como os gentios receberam o Espírito Santo (11:1–18)."], ["Barnabé e Saulo", "Ensinam em Antioquia, onde os discípulos são chamados cristãos (11:22–26)."], ["Ágabo", "Anuncia uma fome (11:27–30)."]], "refs": ["Atos 10:44–48", "Atos 13:1–3", "2 Coríntios 8:13–15"], "family": "Leiam Atos 11:27–30. Escolham alguém que precisa de apoio e planejem uma ajuda que cada pessoa da família possa oferecer.", "points": {"jerusalem": "Pedro relata sua visita aos gentios. De Jerusalém parte Barnabé para Antioquia (11:1–22).", "fenicia": "A Fenícia aparece entre os destinos de discípulos dispersos (11:19).", "chipre": "Chipre é destino da dispersão e origem de alguns que anunciam em Antioquia (11:19–20).", "antioquia": "Barnabé e Saulo ensinam, e a comunidade reúne auxílio para a Judeia (11:22–30)."}, "routes": [["jerusalem", "fenicia", "antioquia"], ["jerusalem", "chipre", "antioquia"]]}, {"chapter": 12, "period": "Por volta de 44 d.C., com referência à morte de Herodes Agripa I", "summary": "Herodes manda matar Tiago e prende Pedro. A igreja ora, e um anjo liberta Pedro. Na casa de Maria, Rode reconhece a voz de Pedro. O capítulo relata a morte de Herodes em Cesareia e registra que a palavra de Deus continuava a se espalhar.", "people": [["Tiago, irmão de João", "É morto por ordem de Herodes (12:1–2)."], ["Pedro", "É libertado da prisão e chega à casa de Maria (12:3–17)."], ["Maria e Rode", "Maria acolhe a reunião de oração. Rode reconhece a voz de Pedro (12:12–16)."], ["Herodes Agripa I", "Persegue a igreja e depois morre em Cesareia (12:1–23)."]], "refs": ["Atos 4:23–31", "Lucas 22:31–32", "Atos 5:17–21"], "family": "Leiam Atos 12:5–17. Contem a história em vozes diferentes e terminem orando juntos por alguém que precisa de encorajamento.", "points": {"jerusalem": "Pedro é preso e libertado. A igreja ora e Rode o reconhece à porta (12:3–17).", "cesareia": "Herodes desce da Judeia para Cesareia, onde a narrativa situa sua morte (12:19–23)."}, "routes": [["jerusalem", "cesareia"]]}];
  const places = {"damasco": [254, 51, "Damasco"], "antioquia": [166, 20, "Antioquia da Síria"], "fenicia": [139, 78, "Fenícia"], "chipre": [55, 63, "Chipre"], "cesareia": [136, 147, "Cesareia"], "samaria": [211, 161, "Região de Samaria"], "jope": [98, 204, "Jope"], "lida": [173, 223, "Lida"], "jerusalem": [219, 265, "Jerusalém"], "gaza": [88, 289, "Gaza"], "azoto": [102, 253, "Azoto"]};
  const access = "\n<section aria-labelledby=\"atlas-share\">\n  <h3 id=\"atlas-share\">Acesso à plataforma</h3>\n  <p><a class=\"atlas-address\" href=\"https://crogerguitar2016-bot.github.io/EBD_KOINONIA/\">https://crogerguitar2016-bot.github.io/EBD_KOINONIA/</a></p>\n</section>\n";
  const nav = document.querySelector('main > nav');
  const atlas = document.createElement('button');
  atlas.id = 'atlas-nav';
  atlas.textContent = 'Explorar Atos 8–12';
  nav.append(atlas);

  // A tela de jogo atualiza o bloqueio sempre que a pergunta muda.
  const sync = () => { atlas.disabled = Boolean(readerLocked()); };
  new MutationObserver(sync).observe(navBible, {attributes:true, attributeFilter:['disabled']});
  sync();

  function mapOf(lesson) {
    const markers = Object.keys(lesson.points).map(key => {
      const [x, y, label] = places[key];
      const rightAligned = x >= 200;
      return `<g class="atlas-place" data-place="${key}" role="button" tabindex="0"
                 aria-label="${escapeHtml(label)}" aria-pressed="false">
        <circle cx="${x}" cy="${y}" r="8" fill="#39765b" stroke="white" stroke-width="2"/>
        <text x="${x + (rightAligned ? -11 : 11)}" y="${y + 4}"
              text-anchor="${rightAligned ? 'end' : 'start'}">${escapeHtml(label)}</text>
      </g>`;
    }).join('');
    const routes = lesson.routes.map(route => {
      const points = route.map(key => places[key].slice(0, 2).join(',')).join(' ');
      return `<polyline points="${points}" fill="none" stroke="#98632f" stroke-width="2.5"
                        stroke-dasharray="6 5"/>`;
    }).join('');
    return `<svg class="atlas-map" viewBox="0 0 290 318" role="group"
                 aria-label="Mapa esquemático de Atos ${lesson.chapter}">
      <path d="M151 0H290V318H59L77 291L94 270L99 243L94 218L113 181L120 141L127 112L130 75Z"
            fill="#f3f0e8"/>
      <ellipse cx="53" cy="63" rx="25" ry="11" fill="#f3f0e8"/>
      <text x="10" y="133">Mediterrâneo</text>
      ${routes}${markers}
    </svg>`;
  }

  function openAtlas() {
    if (readerLocked()) return;
    const item = currentItem();
    if (item && inActivity) {
      item.consults++;
      if (item.choice === null) item.assistedConsults++;
    }
    stopViewing();
    updateNavigation();
    view.innerHTML = `<section aria-labelledby="atlas-title">
      <h2 id="atlas-title" tabindex="-1">Explorar Atos 8–12</h2>
      ${active ? '<button id="atlas-resume">Retomar atividade</button>' : ''}
      <nav class="atlas-controls" aria-label="Capítulos e apresentação">
        <label>Capítulo <select id="atlas-chapter">${lessons.map(lesson =>
          `<option value="${lesson.chapter}">Atos ${lesson.chapter}</option>`).join('')}</select></label>
        <button id="atlas-tv">Apresentar na TV</button>
      </nav>
      <div id="atlas-content"></div>
      <details><summary>Cronologia de Atos 8–12</summary>
        <p>As datas são aproximações históricas. As faixas se sobrepõem porque o
        texto bíblico não informa o ano de cada episódio.</p><ol>${lessons.map(lesson =>
          `<li><strong>Atos ${lesson.chapter}</strong> — ${escapeHtml(lesson.period)}</li>`
        ).join('')}</ol></details>
      ${access}
      <details><summary>Privacidade</summary><p>Respostas e resultados ficam na
      memória da página e são descartados ao recarregar ou fechar. A hospedagem
      pode registrar o acesso ao site. Ao escolher compartilhar pelo WhatsApp ou
      abrir a Bíblia online, você acessa um serviço externo. O nome digitado
      para o certificado é usado na página e na impressão solicitada.</p></details>
    </section>`;
    const picker = document.querySelector('#atlas-chapter');
    const content = document.querySelector('#atlas-content');
    const tv = document.querySelector('#atlas-tv');
    document.querySelector('#atlas-resume')?.addEventListener('click', resume);

    function render() {
      const lesson = lessons.find(entry => entry.chapter === Number(picker.value));
      content.innerHTML = `<h3>Atos ${lesson.chapter}</h3>
        <p class="muted">${escapeHtml(lesson.period)}</p>
        <p>${escapeHtml(lesson.summary)}</p>
        <h3>Mapa</h3><p class="muted">Selecione um local. Os traços indicam
        ligações narrativas, sem escala ou reconstrução do trajeto.</p>
        ${mapOf(lesson)}
        <div class="atlas-points">${Object.keys(lesson.points).map(key =>
          `<button data-place="${key}" aria-pressed="false">${escapeHtml(places[key][2])}</button>`
        ).join('')}</div>
        <p class="atlas-place-info" role="status"></p>
        <h3>Personagens</h3><ul>${lesson.people.map(([name, note]) =>
          `<li><strong>${escapeHtml(name)}</strong> — ${escapeHtml(note)}</li>`).join('')}</ul>
        <h3>Referências complementares</h3><ul>${lesson.refs.map(ref =>
          `<li>${escapeHtml(ref)}</li>`).join('')}</ul>
        <button id="atlas-reader">Abrir consulta bíblica</button>
        <h3>Desafio em família</h3><p>${escapeHtml(lesson.family)}</p>`;
      document.querySelector('#atlas-reader').onclick = () => bible(lesson.chapter);
      const markers = Array.from(content.querySelectorAll('[data-place]'));
      const info = content.querySelector('.atlas-place-info');
      function selectPlace(key) {
        for (const marker of markers) {
          marker.setAttribute('aria-pressed', String(marker.dataset.place === key));
        }
        info.textContent = `${places[key][2]} — ${lesson.points[key]}`;
      }
      for (const marker of markers) {
        marker.onclick = () => selectPlace(marker.dataset.place);
        if (marker.namespaceURI === 'http://www.w3.org/2000/svg') {
          marker.onkeydown = event => {
            if (event.key === 'Enter' || event.key === ' ') {
              event.preventDefault();
              selectPlace(marker.dataset.place);
            }
          };
        }
      }
      selectPlace(Object.keys(lesson.points)[0]);
    }

    picker.addEventListener('change', render);
    tv.addEventListener('click', () => present(Number(picker.value), tv));
    render();
    document.querySelector('#atlas-title').focus();
  }

  function present(chapterNumber, opener) {
    if (readerLocked()) return;
    const slides = lessons.flatMap(lesson => [
      {lesson, title:'Resumo do capítulo', description:lesson.summary},
      {lesson, title:'Locais da narrativa', map:true},
      {lesson, title:'Desafio em família', description:lesson.family}
    ]);
    let index = slides.findIndex(slide => slide.lesson.chapter === chapterNumber);
    const dialog = document.createElement('dialog');
    dialog.className = 'atlas-slide';
    dialog.setAttribute('aria-labelledby', 'atlas-slide-title');
    dialog.innerHTML = `<div class="atlas-slide-controls">
      <button data-step="-1">Anterior</button><button data-step="1">Próximo</button>
      <button data-full>Tela cheia</button><button data-exit autofocus>Sair</button>
      </div><div data-slide></div><p data-count role="status"></p>`;
    document.body.append(dialog);
    const body = dialog.querySelector('[data-slide]');
    const previous = dialog.querySelector('[data-step="-1"]');
    const next = dialog.querySelector('[data-step="1"]');
    const full = dialog.querySelector('[data-full]');
    function renderSlide() {
      const {lesson, title, description, map} = slides[index];
      body.innerHTML = `<p>Atos ${lesson.chapter} · ${escapeHtml(lesson.period)}</p>
        <h2 id="atlas-slide-title">${escapeHtml(title)}</h2>
        ${map ? mapOf(lesson) + `<p>${Object.keys(lesson.points).map(key =>
          escapeHtml(places[key][2])).join(' · ')}</p>` : `<p>${escapeHtml(description)}</p>`}`;
      for (const marker of body.querySelectorAll('[data-place]')) {
        for (const attr of ['role', 'tabindex', 'aria-pressed', 'data-place']) marker.removeAttribute(attr);
      }
      dialog.querySelector('[data-count]').textContent = `${index + 1} de ${slides.length}`;
      previous.disabled = index === 0;
      next.disabled = index === slides.length - 1;
    }
    function move(step) {
      index = Math.max(0, Math.min(slides.length - 1, index + step));
      renderSlide();
      if (document.activeElement === previous && previous.disabled) next.focus();
      if (document.activeElement === next && next.disabled) previous.focus();
    }
    previous.onclick = () => move(-1);
    next.onclick = () => move(1);
    dialog.querySelector('[data-exit]').onclick = () => dialog.close();
    full.hidden = !dialog.requestFullscreen;
    full.onclick = async () => {
      try {
        if (document.fullscreenElement === dialog) await document.exitFullscreen();
        else await dialog.requestFullscreen();
      } catch {
        full.hidden = true;
      }
    };
    dialog.addEventListener('keydown', event => {
      if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
      event.preventDefault();
      move(event.key === 'ArrowLeft' ? -1 : 1);
    });
    dialog.addEventListener('close', () => {
      if (document.fullscreenElement === dialog) document.exitFullscreen().catch(() => {});
      dialog.remove();
      opener.focus();
    }, {once:true});
    renderSlide();
    dialog.showModal();
  }

  atlas.addEventListener('click', openAtlas);
})();
